window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-fb54306aca5351d6"]={"versions": [{"id": "FIG-fb54306aca5351d6", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für Zeitbeschränkungen (Timing Constraints) innerhalb der AUTOSAR Adaptive Platform Timing Extensions. Das Diagramm modelliert die strukturelle Einbettung von <code>OffsetTimingConstraint</code> in das übergeordnete AUTOSAR-Timing-Metamodell und definiert dessen Beziehungen zu Referenzereignissen sowie Zeitangaben.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><strong>OffsetTimingConstraint</strong>:</li>\n<li>Spezialisiert <code>TimingConstraint::TimingConstraint</code> (über Vererbung, welche ihrerseits <code>Identifiable</code> und <code>Traceable</code> darstellt).</li>\n<li>Besitzt eine gerichtete Assoziation <code>+source</code> mit Multiplizität <code>1</code> auf <code>TimingDescription::TimingDescriptionEvent</code> (im Kontext <code>TimingDescription</code>).</li>\n<li>Besitzt eine gerichtete Assoziation <code>+target</code> mit Multiplizität <code>1</code> auf <code>TimingDescription::TimingDescriptionEvent</code> (im Kontext <code>TimingDescription</code>).</li>\n<li>Enthält per Komposition über die Rollen <code>+minimum</code> (Multiplizität <code>1</code>) und <code>+maximum</code> (Multiplizität <code>1</code>) jeweils eine Instanz von <code>MultidimensionalTime::MultidimensionalTime</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>MultidimensionalTime::MultidimensionalTime</strong>:</li>\n<li>Enthält die Attribute <code>+ cseCode: CseCodeType</code> und <code>+ cseCodeFactor: Integer</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>TimingDescription::TimingDescriptionEvent</strong>:</li>\n<li>Dient als Zieltyp für Start- und Zielereignisse der zeitlichen Versatzmessung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Ablaufmodellierung. Semantisch beschreibt das Diagramm die Beschränkung der zeitlichen Distanz zwischen dem Eintreten eines Quellereignisses (<code>source</code>) und eines Zielereignisses (<code>target</code>), begrenzt durch eine minimale (<code>minimum</code>) und maximale (<code>maximum</code>) Zeitspanne.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für AUTOSAR-Modellierer und Tool-Entwickler verbindlich:</p>\n<ul class=\"fig-list\">\n<li>Instanzen von <code>OffsetTimingConstraint</code> müssen strikt genau ein Quell- und genau ein Zielereignis (<code>TimingDescriptionEvent</code>) referenzieren.</li>\n<li>Sowohl die minimale (<code>minimum</code>) als auch die maximale Grenze (<code>maximum</code>) müssen als vollständige <code>MultidimensionalTime</code>-Struktur mit jeweils gesetztem <code>cseCode</code> und <code>cseCodeFactor</code> vorliegen.</li>\n</ul>"}, {"id": "FIG-0081e07165a8b5b8", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für Zeitbeschränkungen (Timing Constraints) innerhalb der AUTOSAR Adaptive Platform Timing Extensions. Das Diagramm modelliert die strukturelle Einbettung von <code>OffsetTimingConstraint</code> in das übergeordnete AUTOSAR-Timing-Metamodell und definiert dessen Beziehungen zu Referenzereignissen sowie Zeitangaben.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><strong>OffsetTimingConstraint</strong>:</li>\n<li>Spezialisiert <code>TimingConstraint</code> (über Vererbung, welche ihrerseits <code>Identifiable</code> und <code>Traceable</code> darstellt).</li>\n<li>Besitzt eine gerichtete Assoziation <code>+source</code> mit Multiplizität <code>1</code> auf <code>TimingDescriptionEvent</code> (im Kontext <code>TimingDescription</code>).</li>\n<li>Besitzt eine gerichtete Assoziation <code>+target</code> mit Multiplizität <code>1</code> auf <code>TimingDescriptionEvent</code> (im Kontext <code>TimingDescription</code>).</li>\n<li>Enthält per Komposition über die Rollen <code>+minimum</code> (Multiplizität <code>1</code>) und <code>+maximum</code> (Multiplizität <code>1</code>) jeweils eine Instanz von <code>MultidimensionalTime</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>MultidimensionalTime</strong>:</li>\n<li>Enthält die Attribute <code>+ cseCode: CseCodeType</code> und <code>+ cseCodeFactor: Integer</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>TimingDescriptionEvent</strong>:</li>\n<li>Dient als Zieltyp für Start- und Zielereignisse der zeitlichen Versatzmessung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Ablaufmodellierung. Semantisch beschreibt das Diagramm die Beschränkung der zeitlichen Distanz zwischen dem Eintreten eines Quellereignisses (<code>source</code>) und eines Zielereignisses (<code>target</code>), begrenzt durch eine minimale (<code>minimum</code>) und maximale (<code>maximum</code>) Zeitspanne.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für AUTOSAR-Modellierer und Tool-Entwickler verbindlich:</p>\n<ul class=\"fig-list\">\n<li>Instanzen von <code>OffsetTimingConstraint</code> müssen strikt genau ein Quell- und genau ein Zielereignis (<code>TimingDescriptionEvent</code>) referenzieren.</li>\n<li>Sowohl die minimale (<code>minimum</code>) als auch die maximale Grenze (<code>maximum</code>) müssen als vollständige <code>MultidimensionalTime</code>-Struktur mit jeweils gesetztem <code>cseCode</code> und <code>cseCodeFactor</code> vorliegen.</li>\n</ul>"}, {"id": "FIG-1383d1ddd1c2b530", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für Zeitbeschränkungen (Timing Constraints) innerhalb der AUTOSAR Adaptive Platform Timing Extensions. Das Diagramm modelliert die strukturelle Einbettung von <code>OffsetTimingConstraint</code> in das übergeordnete AUTOSAR-Timing-Metamodell und definiert dessen Beziehungen zu Referenzereignissen sowie Zeitangaben.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><strong>OffsetTimingConstraint</strong>:</li>\n<li>Spezialisiert <code>TimingConstraint</code> (über Vererbung, welche ihrerseits <code>Identifiable</code> und <code>Traceable</code> darstellt).</li>\n<li>Besitzt eine gerichtete Assoziation <code>+source</code> mit Multiplizität <code>0..1</code> auf <code>TimingDescriptionEvent</code> (im Kontext <code>TimingDescription</code>).</li>\n<li>Besitzt eine gerichtete Assoziation <code>+target</code> mit Multiplizität <code>0..1</code> auf <code>TimingDescriptionEvent</code> (im Kontext <code>TimingDescription</code>).</li>\n<li>Enthält per Komposition über die Rollen <code>+minimum</code> (Multiplizität <code>0..1</code>) und <code>+maximum</code> (Multiplizität <code>0..1</code>) Instanzen von <code>MultidimensionalTime</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>MultidimensionalTime</strong>:</li>\n<li>Enthält die optionalen Attribute <code>+ cseCode: CseCodeType [0..1]</code> und <code>+ cseCodeFactor: Integer [0..1]</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>TimingDescriptionEvent</strong>:</li>\n<li>Dient als Zieltyp für Start- und Zielereignisse der zeitlichen Versatzmessung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Ablaufmodellierung. Semantisch beschreibt das Diagramm die Beschränkung der zeitlichen Distanz zwischen dem Eintreten eines Quellereignisses (<code>source</code>) und eines Zielereignisses (<code>target</code>), begrenzt durch eine minimale (<code>minimum</code>) und maximale (<code>maximum</code>) Zeitspanne.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für AUTOSAR-Modellierer und Tool-Entwickler verbindlich:</p>\n<ul class=\"fig-list\">\n<li>Referenzen auf <code>source</code> und <code>target</code> (<code>TimingDescriptionEvent</code>) sind optional (Multiplizität <code>0..1</code>).</li>\n<li>Sowohl die minimale (<code>minimum</code>) als auch die maximale Grenze (<code>maximum</code>) sind optional (<code>0..1</code>).</li>\n<li>Innerhalb von <code>MultidimensionalTime</code> sind die Attribute <code>cseCode</code> und <code>cseCodeFactor</code> jeweils optional mit Kardinalität <code>[0..1]</code> ausgeprägt.</li>\n</ul>"}], "trans": [{"from": "FIG-fb54306aca5351d6", "to": "FIG-0081e07165a8b5b8", "fr": "R20-11", "tr": "R21-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Entfernung der redundanten Paketpräfixe in den Klassennamen: <code>TimingConstraint::TimingConstraint</code> zu <code>TimingConstraint</code>, <code>TimingDescription::TimingDescriptionEvent</code> zu <code>TimingDescriptionEvent</code> sowie <code>MultidimensionalTime::MultidimensionalTime</code> zu <code>MultidimensionalTime</code>.</li>\n</ul>"}, {"from": "FIG-0081e07165a8b5b8", "to": "FIG-1383d1ddd1c2b530", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Kardinalitätsänderung der Kompositionsrollen <code>+minimum</code> und <code>+maximum</code> von <code>OffsetTimingConstraint</code> zu <code>MultidimensionalTime</code> von <code>1</code> auf <code>0..1</code>.</li>\n<li>Kardinalitätsänderung der Assoziationsrollen <code>+source</code> und <code>+target</code> von <code>OffsetTimingConstraint</code> zu <code>TimingDescriptionEvent</code> von <code>1</code> auf <code>0..1</code>.</li>\n<li>Kardinalitätsänderung der Attribute <code>cseCode: CseCodeType</code> und <code>cseCodeFactor: Integer</code> in <code>MultidimensionalTime</code> von implizit <code>1</code> auf <code>[0..1]</code>.</li>\n</ul>"}]};
